// s05 ink layers: draws the measured drawing data in ./data/*.js (generated by ./trace/, see trace/README.md).
// A layer is a value study (nested iso-value regions, each filled over the last, then softened with a gaussian) with
// the ink strokes on top (tapered centre-lines, dark ones first, then the white lines), tinted like the source's
// green-grey ink, and cut to the layer's outline. Everything is deterministic; each layer is built once and cached.
import { taper } from "../../lib/ink.js";

// ---- decoding (see trace/export.py): zig-zag integers in 5-bit groups, one char each (+63), 0x20 = more follows
export function decode(s) {
  const out = [];
  let i = 0;
  while (i < s.length) {
    let z = 0, sh = 0, b;
    do { b = s.charCodeAt(i++) - 63; z += (b & 0x1f) * Math.pow(2, sh); sh += 5; } while (b >= 0x20);
    out.push(z % 2 ? -(z + 1) / 2 : z / 2);
  }
  return out;
}
// rings: n, x0, y0, dx, dy, ... in quarter px -> [[x, y], ...] per ring (layer-box coordinates)
export function decodeRings(s) {
  const a = decode(s), rings = [];
  let i = 0;
  while (i < a.length) {
    const n = a[i++]; let x = a[i++], y = a[i++];
    const r = [[x / 4, y / 4]];
    for (let k = 1; k < n; k++) { x += a[i++]; y += a[i++]; r.push([x / 4, y / 4]); }
    rings.push(r);
  }
  return rings;
}
// strokes: v*4 + caps, n, x0, y0, w0, dx, dy, dw, ... -> [{ v, caps, pts: [[x, y]], w: [..] }]
// (caps: 1 = the stroke's start tapers, 2 = its end tapers; chunks of one long line join at full width)
export function decodeStrokes(s) {
  const a = decode(s), out = [];
  let i = 0;
  while (i < a.length) {
    const vc = a[i++], v = Math.floor(vc / 4) / 1000, caps = vc % 4, n = a[i++];
    let x = a[i++], y = a[i++], w = a[i++];
    const pts = [[x / 4, y / 4]], ws = [w / 20];
    for (let k = 1; k < n; k++) { x += a[i++]; y += a[i++]; w += a[i++]; pts.push([x / 4, y / 4]); ws.push(w / 20); }
    out.push({ v, caps, pts, w: ws });
  }
  return out;
}

const ringsPath = (g, rings) => { for (const r of rings) { g.moveTo(r[0][0], r[0][1]); for (let k = 1; k < r.length; k++) g.lineTo(r[k][0], r[k][1]); g.closePath(); } };
const grey = (v) => { const c = Math.max(0, Math.min(255, Math.round(v * 255))); return `rgb(${c},${c},${c})`; };

// separable gaussian on one channel (Float32), exact and deterministic
export function gauss1(src, w, h, sigma) {
  if (sigma <= 0) return src;
  const r = Math.ceil(sigma * 3), k = new Float32Array(2 * r + 1);
  let sum = 0;
  for (let i = -r; i <= r; i++) { k[i + r] = Math.exp(-0.5 * (i * i) / (sigma * sigma)); sum += k[i + r]; }
  for (let i = 0; i < k.length; i++) k[i] /= sum;
  const tmp = new Float32Array(w * h), out = new Float32Array(w * h);
  for (let y = 0; y < h; y++) {
    const o = y * w;
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let j = -r; j <= r; j++) { const xx = x + j < 0 ? 0 : x + j >= w ? w - 1 : x + j; s += src[o + xx] * k[j + r]; }
      tmp[o + x] = s;
    }
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let j = -r; j <= r; j++) { const yy = y + j < 0 ? 0 : y + j >= h ? h - 1 : y + j; s += tmp[yy * w + x] * k[j + r]; }
      out[y * w + x] = s;
    }
  }
  return out;
}

// the stroke outline, as in trace/sim.py stroke_poly(): tapering ends at 0.55 of the measured width
export const END_TAPER = 0.55;
function drawStroke(g, st, color) {
  const n = st.pts.length;
  if (n < 2) return;
  taper(g, st.pts, (u) => { const i = Math.round(u * (n - 1)); return st.w[i] * ((i === 0 && st.caps & 1) || (i === n - 1 && st.caps & 2) ? END_TAPER : 1); }, color);
  // chunk joints: a round cap so consecutive chunks of one line close up
  for (const [bit, i] of [[1, 0], [2, n - 1]]) if (!(st.caps & bit)) { g.beginPath(); g.arc(st.pts[i][0], st.pts[i][1], st.w[i] / 2, 0, Math.PI * 2); g.fill(); }
}

// The print texture (trace/tone.py): the source's lit areas carry a fine screentone, a crosshatch at 45° and 135° with a
// 2.95 px period. D.tone holds its local amplitude as nested iso-amplitude outlines; the pattern is laid in frame
// coordinates (so it stays put as layers overlap) and moves with its layer.
// (gain: the layer's final softening, σ 0.5, takes a 2.95 px pattern down to exp(-2π²σ²/p²) = 0.57 of itself)
export const TONE = { period: 2.95, max: 0.05, scale: 8, gain: 1.75 };
function addTone(b, D, w, h) {
  const [x0, y0] = D.box;
  const c = document.createElement("canvas"); c.width = w; c.height = h;
  const g = c.getContext("2d");
  g.fillStyle = "#000"; g.fillRect(0, 0, w, h);
  for (const [v, s] of D.tone) { g.beginPath(); ringsPath(g, decodeRings(s)); g.fillStyle = grey(Math.min(TONE.max, v / 1000) * TONE.scale); g.fill("evenodd"); }
  const id = g.getImageData(0, 0, w, h).data, a = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) a[i] = id[i * 4];
  const A = gauss1(a, w, h, 3), k = (2 * Math.PI) / TONE.period / Math.SQRT2;
  for (let y = 0; y < h; y++) {
    const Y = y + y0 + 0.5;
    for (let x = 0; x < w; x++) {
      const i = y * w + x, amp = (A[i] / TONE.scale) * TONE.gain;          // (0..255 value units)
      if (amp < 0.05) continue;
      const X = x + x0 + 0.5;
      b[i] += amp * 0.5 * (Math.cos(k * (X + Y)) + Math.cos(k * (Y - X)));
    }
  }
}

// the source's ink is a green-grey: pre-grade channels = a * value + b (fitted on the settled frame, trace/build.py)
export const TINT = { r: [1.0, -0.006], g: [1.0, 0.014], b: [1.0, -0.008] };

// Build a layer canvas from its data module D. Returns { c, x, y, w, h } in frame px (box origin).
// opts: blur (value study softening, px), soft (final softening of the whole layer, px), strokes (false = value study only),
// cut (false: not cut to the outline yet)
// keep(st) (optional): which strokes to draw; under(g) (optional): paints into the value study (box coordinates) before
// the strokes go on
export function buildInkLayer(D, { blur = 1.6, soft = 0, strokes = true, tint = TINT, cut = true, tone = true, keep = null, under = null } = {}) {
  const [x0, y0, x1, y1] = D.box, w = x1 - x0, h = y1 - y0;
  const c = document.createElement("canvas"); c.width = w; c.height = h;
  const g = c.getContext("2d");
  g.fillStyle = grey(D.base0 / 1000); g.fillRect(0, 0, w, h);
  for (const [v, s] of D.levels) { g.beginPath(); ringsPath(g, decodeRings(s)); g.fillStyle = grey(v / 1000); g.fill("evenodd"); }
  // soften the value study (one channel), then lay the print texture into it
  let id = g.getImageData(0, 0, w, h), px = id.data;
  if (blur > 0 || (tone && D.tone && D.tone.length)) {
    const f = new Float32Array(w * h);
    for (let i = 0; i < w * h; i++) f[i] = px[i * 4];
    const b = blur > 0 ? gauss1(f, w, h, blur) : f;
    if (tone && D.tone && D.tone.length) addTone(b, D, w, h);
    for (let i = 0; i < w * h; i++) { const v = Math.max(0, Math.min(255, Math.round(b[i]))); px[i * 4] = px[i * 4 + 1] = px[i * 4 + 2] = v; px[i * 4 + 3] = 255; }
    g.putImageData(id, 0, 0);
  }
  if (under) { g.save(); under(g); g.restore(); }
  if (strokes) for (const st of decodeStrokes(D.strokes)) if (!keep || keep(st)) drawStroke(g, st, grey(st.v));
  // tint (+ optional final softening)
  id = g.getImageData(0, 0, w, h); px = id.data;
  let f = null;
  if (soft > 0) { f = new Float32Array(w * h); for (let i = 0; i < w * h; i++) f[i] = px[i * 4]; f = gauss1(f, w, h, soft); }
  const lut = (ch) => { const [a, b] = tint[ch], L = new Uint8ClampedArray(256); for (let v = 0; v < 256; v++) L[v] = Math.round(v * a + b * 255); return L; };
  const LR = lut("r"), LG = lut("g"), LB = lut("b");
  for (let i = 0; i < w * h; i++) {
    const v = f ? Math.max(0, Math.min(255, Math.round(f[i]))) : px[i * 4];
    px[i * 4] = LR[v]; px[i * 4 + 1] = LG[v]; px[i * 4 + 2] = LB[v]; px[i * 4 + 3] = 255;
  }
  g.putImageData(id, 0, 0);
  // cut to the layer outline (opts.cut = false: leave it uncut, see cutLayer)
  if (cut) cutTo(c, D, 0);
  return { c, x: x0, y: y0, w, h };
}

// cut a canvas (in the layer's box coordinates) to the layer's outline, grown by `grow` px
function cutTo(c, D, grow) {
  if (!D.alpha || !D.alpha.length) return c;
  const g = c.getContext("2d");
  g.save(); g.globalCompositeOperation = "destination-in"; g.beginPath(); ringsPath(g, decodeRings(D.alpha));
  if (grow > 0) {
    // fill + a stroke of the outline, drawn into a mask first so destination-in sees their union
    const m = document.createElement("canvas"); m.width = c.width; m.height = c.height;
    const q = m.getContext("2d"); q.beginPath(); ringsPath(q, decodeRings(D.alpha)); q.fillStyle = "#fff"; q.fill("evenodd");
    q.lineWidth = 2 * grow; q.lineJoin = "round"; q.strokeStyle = "#fff"; q.stroke();
    g.drawImage(m, 0, 0);
  } else { g.fillStyle = "#fff"; g.fill("evenodd"); }
  g.restore();
  return c;
}
// a copy of an uncut layer { c, x, y, w, h } cut to D's outline grown by `grow` px
export function cutLayer(l, D, grow = 0) {
  const c = document.createElement("canvas"); c.width = l.c.width; c.height = l.c.height;
  c.getContext("2d").drawImage(l.c, 0, 0);
  return { ...l, c: cutTo(c, D, grow) };
}
